# region: shape
def shape(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: intake
def intake(xs, offset=1):
    return [v + offset for v in xs]

# region: digest
def digest(xs, factor=2):
    return [v * factor for v in xs[1:]]

# region: gather
def gather(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: sift
def sift(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return sift(gather(digest(intake(shape(raw)))))

