        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'total': 56, 'grade': 'high'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'total': 2, 'grade': 'low'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'total': 56, 'grade': 'high'})
